<template>
  <DocBitsTable
    :rows="tableRows"
    :columns="cols"
    row-key="id"
    table-id="export_history_table"
    :features="{
      sorting: false,
      filtering: false,
      selection: false,
      bulkActions: false,
      rowActions: false,
      resizable: false,
      pagination: false,
      columnReorder: false,
    }"
    no-data-label="no_record_found"
    flat-style
  >
    <template #body-cell-filters="{ row }">
      <div class="flex flex-wrap gap-1">
        <template
          v-for="filters in getUsedFilters(row.filters)"
          :key="filters.name"
        >
          <q-chip
            class="text-capitalize"
            :label="filters.name + ': ' + filters.value"
            color="primary"
            size="sm"
            text-color="white"
          />
        </template>
      </div>
    </template>
    <template #body-cell-created_on="{ row }">
      {{ formatDateAccordingToPreference(row.created_on) }}
    </template>
    <template #body-cell-completed_at="{ row }">
      {{ formatDateAccordingToPreference(row.completed_at) }}
    </template>
  </DocBitsTable>
</template>

<script lang="ts">
import dateUtils from 'src/utils/date';
import { defineComponent, ref } from 'vue';
import { exportApiService } from 'src/services';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import { notify } from 'src/components/notifications/notify';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import type { UnifiedTableColumn } from 'src/components/Table/types/table/unified-table';

export default defineComponent({
  name: 'ExportHistory',
  mixins: [dateUtils],
  components: { DocBitsTable },
  setup() {
    const cols: UnifiedTableColumn[] = [
      { name: 'email_sent_to', label: 'Email', align: 'left', field: 'email_sent_to' },
      { name: 'status', label: 'Status', align: 'left', field: 'status' },
      { name: 'created_on', label: 'Requested At', align: 'left', field: 'created_on' },
      { name: 'completed_at', label: 'Completed At', align: 'left', field: 'completed_at' },
      { name: 'format', label: 'Format', align: 'left', field: 'format' },
      { name: 'filters', label: 'Filters Used', align: 'left', field: 'filters' },
    ];
    return {
      cols,
      tableRows: ref([] as any),
    };
  },
  mounted() {
    this.fetchExportHistory();
  },
  methods: {
    getUsedFilters(filters: string): dynamicObj[] {
      const jsonFilters: [dynamicObj] = JSON.parse(filters);
      const usedFilters = [] as dynamicObj[];
      Object.keys(jsonFilters).forEach((filter: any) => {
        if (filter === 'org_id' || filter === 'sub_org_id') {
          if (jsonFilters[filter] === jsonFilters['sub_org_id' as any]) {
            return;
          }
        }
        const filterValue: any = jsonFilters[filter];
        if (Array.isArray(filterValue)) {
          if (filterValue.length == 0) {
            return;
          }
        }
        if (filterValue && filterValue !== '') {
          const filterObject = {
            name: filter.replace(/_/g, ' '),
            value: jsonFilters[filter],
          };
          usedFilters.push(filterObject);
        }
      });
      return usedFilters;
    },
    async fetchExportHistory() {
      try {
        const response = await exportApiService.fetchExportHistory();
        if (!response.success) {
          throw response.exception;
        }
        this.tableRows = response.data;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
  },
});
</script>
