<template>
  <q-item>
    <q-item-section>
      <q-item-label>{{ $t('export_dashboard_data') }}</q-item-label>
    </q-item-section>
    <q-item-section side>
      <f-toggle
        size="xs"
        v-model="user_settings[setting_name]"
        @update:model-value="
          (val: boolean) => {
            saveSettings(setting_name, val);
          }
        "
      />
    </q-item-section>
  </q-item>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { useSettingStore } from 'src/store/main';
import { ApiExceptions } from 'src/exceptions/index';
export default defineComponent({
  el: '#app',
    props: [],
  components: {},
  data() {
    return {
      setting_name: 'EXPORT_DASHBOARD_DATA',
    };
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        // data loading is done and value never set
        if (newVal == false && oldVal == true) {
          if (!this.user_settings[this.setting_name]) {
            this.user_settings[this.setting_name] = false;
          }
        }
      },
    },
  },
  setup() {
    const settings_store = useSettingStore();
    const { updateSetting } = settings_store;
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    return {
      updateSetting,
      user_settings,
      loading_settings,
      loading: ref(false),
    };
  },
  methods: {
    async saveSettings(key: string, value: any) {
      if (!key) {
        return;
      }
      try {
        this.loading = true;
        await this.updateSetting(key, value);
        notify.success(this.$t('MSG_SAVE'));
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },
  },
});
</script>
