<template>
  <div class="page-container page-height-limit" data-test="settings-dashboard-page">
    <div class="settings-page-content" data-test="settings-page-content">
      <!-- General Settings -->
      <docbits-accordion-panel
        v-model="expandedSections.general"
        icon="mdi:cog"
        :title="$t('general')"
        bodyClass="settings-card"
      >
        <General />
      </docbits-accordion-panel>

      <!-- Export History -->
      <docbits-accordion-panel
        v-model="expandedSections.exportHistory"
        icon="mdi:history"
        :title="$t('export_history')"
        bodyClass="settings-card"
      >
        <ExportHistory />
      </docbits-accordion-panel>

      <!-- Action -->
      <docbits-accordion-panel
        v-model="expandedSections.action"
        icon="mdi:gesture-tap"
        :title="$t('action')"
        bodyClass="settings-card"
      >
        <Action />
      </docbits-accordion-panel>

      <template v-if="isAdmin">
        <!-- Filter Settings -->
        <docbits-accordion-panel
          v-model="expandedSections.filters"
          icon="mdi:filter-variant"
          :title="$t('filters')"
          bodyClass="settings-card"
        >
          <StatusFilter />
        </docbits-accordion-panel>

        <!-- ASN Dashboard -->
        <docbits-accordion-panel
          v-model="expandedSections.asn"
          icon="mdi:truck"
          :title="$t('advance_shipment_dashboard')"
          bodyClass="settings-card"
        >
          <AdvanceDashboard />
        </docbits-accordion-panel>
      </template>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { useSettingStore } from 'src/store/main';
import { getUserDetailFromkey } from 'src/utils/UserDetails';
import Action from 'src/pages/Settings/Components/Dashboard/Action.vue';
import General from 'src/pages/Settings/Components/Dashboard/General.vue';
import ExportHistory from 'src/pages/Settings/Components/ExportHistory.vue';
import StatusFilter from 'src/pages/Settings/Components/Dashboard/StatusFilter.vue';
import AdvanceDashboard from 'src/pages/Settings/Components/Dashboard/AdvanceDashboard.vue';

export default defineComponent({
  el: '#app',
  components: {
    General,
    ExportHistory,
    StatusFilter,
    AdvanceDashboard,
    Action,
  },
  data() {
    return {
      isAdmin: ref(false),
      expandedSections: {
        general: true,
        exportHistory: true,
        action: true,
        filters: true,
        asn: true,
      } as Record<string, boolean>,
    };
  },
  mounted() {
    this.isAdmin = Boolean(
      JSON.parse(getUserDetailFromkey('is_organisation_admin')),
    );
  },
  setup() {
    const settings_store = useSettingStore();
    const { startSettingsFetch } = settings_store;
    return {
      startSettingsFetch,
    };
  },
});
</script>
