<template>
  <div class="settings-section-label">{{ $t('reset_filters') }}</div>

  <div class="settings-toggle-item">
    <div class="settings-toggle-content">
      <span class="settings-toggle-label">{{ $t('after_upload_doc') }}</span>
    </div>
    <div class="settings-toggle-actions">
      <f-toggle
        size="xs"
        v-model="user_settings[filters_reset_after_upload_setting]"
        @update:model-value="
          updateGeneralDashboardSetting(
            user_settings[filters_reset_after_upload_setting],
            filters_reset_after_upload_setting,
          )
        "
      />
    </div>
  </div>

  <div class="settings-toggle-item">
    <div class="settings-toggle-content">
      <span class="settings-toggle-label">{{ $t('after_document_restart') }}</span>
    </div>
    <div class="settings-toggle-actions">
      <f-toggle
        size="xs"
        v-model="user_settings[filters_reset_after_restart_setting]"
        @update:model-value="
          updateGeneralDashboardSetting(
            user_settings[filters_reset_after_restart_setting],
            filters_reset_after_restart_setting,
          )
        "
      />
    </div>
  </div>

  <div class="settings-toggle-item">
    <div class="settings-toggle-content">
      <span class="settings-toggle-label">{{ $t('after_document_export') }}</span>
    </div>
    <div class="settings-toggle-actions">
      <f-toggle
        size="xs"
        v-model="user_settings[filters_reset_after_export_setting]"
        @update:model-value="
          updateGeneralDashboardSetting(
            user_settings[filters_reset_after_export_setting],
            filters_reset_after_export_setting,
          )
        "
      />
    </div>
  </div>

  <q-separator spaced />

  <div class="settings-section-label">{{ $t('dashboard_data') }}</div>

  <div class="settings-toggle-item">
    <div class="settings-toggle-content">
      <span class="settings-toggle-label">{{ $t('auto_refresh_dashboard_on_update') }}</span>
    </div>
    <div class="settings-toggle-actions">
      <f-toggle
        size="xs"
        v-model="user_settings[auto_refresh_dashboard_on_update]"
        @update:model-value="
          updateGeneralDashboardSetting(
            user_settings[auto_refresh_dashboard_on_update],
            auto_refresh_dashboard_on_update,
          )
        "
      />
    </div>
  </div>

  <ExportDashboardData />
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useSettingStore } from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin.js';
import ExportDashboardData from 'src/pages/Settings/Components/Modules/ExportDashboardData.vue';
import {
  CONSTANTS,
  filters_reset_after_upload_setting,
  filters_reset_after_restart_setting,
  filters_reset_after_export_setting,
  status_filter_style_setting,
  activate_long_cache,
} from 'src/constants';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions';
export default defineComponent({
  components: {
    ExportDashboardData,
  },
  el: '#app',
  mixins: [helperMixin],
  data() {
    return {
      filters_reset_after_upload_setting,
      filters_reset_after_restart_setting,
      filters_reset_after_export_setting,
      status_filter_style_setting,
      activate_long_cache,
      auto_refresh_dashboard_on_update:
        CONSTANTS.auto_refresh_dashboard_on_update,
    };
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        // data loading is done and value never set
        if (newVal == true && oldVal == false) {
          return;
        }
        this.initView();
      },
    },
  },
  mounted: function () {
    this.initView();
  },
  methods: {
    initView() {
      if (!this.user_settings[this.filters_reset_after_upload_setting]) {
        this.user_settings[this.filters_reset_after_upload_setting] = false;
      }

      if (!this.user_settings[this.filters_reset_after_restart_setting]) {
        this.user_settings[this.filters_reset_after_restart_setting] = false;
      }

      if (!this.user_settings[this.filters_reset_after_export_setting]) {
        this.user_settings[this.filters_reset_after_export_setting] = false;
      }

      if (!this.user_settings[this.status_filter_style_setting]) {
        this.user_settings[this.status_filter_style_setting] = 'All';
      }

      if (!this.user_settings[this.activate_long_cache]) {
        this.user_settings[this.activate_long_cache] = false;
      }
    },
    async updateGeneralDashboardSetting(value: any, key: string) {
      try {
        await this.updateSetting(key, value);
        notify.success(this.$t('save_successfully'));
      } catch (error: any) {
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
        logError(error);
      }
    },
  },
  setup() {
    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { updateSetting } = settings_store;

    const status_filter_options = ['All', 'Static'];

    return {
      updateSetting,
      user_settings,
      loading_settings,
      loading: ref(false),
      status_filter_options: status_filter_options,
    };
  },
});
</script>

<style lang="scss" scoped></style>
