<template>
  <div class="settings-toggle-item-with-selects">
    <div class="settings-toggle-content">
      <span class="settings-toggle-label">{{ $t('assign2') }}</span>
    </div>
    <div class="settings-toggle-selects">
      <q-select
        outlined
        dense
        emit-value
        map-options
        class="s-field back-white"
        v-model="user_settings[action_assign_to]"
        @update:model-value="
          updateActionSetting(
            user_settings[action_assign_to],
            action_assign_to,
          )
        "
        :options="assign_to_option"
      />
    </div>
  </div>

  <div class="settings-toggle-item-with-selects">
    <div class="settings-toggle-content">
      <span class="settings-toggle-label">{{ $t('restart') }}</span>
    </div>
    <div class="settings-toggle-selects">
      <q-select
        outlined
        dense
        emit-value
        map-options
        class="s-field back-white"
        v-model="user_settings[action_restart]"
        @update:model-value="
          updateActionSetting(user_settings[action_restart], action_restart)
        "
        :options="restart_option"
      />
    </div>
  </div>

  <div class="settings-toggle-item">
    <div class="settings-toggle-content">
      <span class="settings-toggle-label">{{ $t('return_to_validation_setting') }}</span>
    </div>
    <div class="settings-toggle-actions">
      <f-toggle
        v-model="user_settings[action_return_to_validation]"
        size="xs"
        @update:model-value="
          updateActionSetting(user_settings[action_return_to_validation], action_return_to_validation)
        "
      />
    </div>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import helperMixin from 'src/mixins/helperMixin.js';
import { useSettingStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import {
  action_assign_to,
  action_restart,
  assign_to_option,
  restart_option,
  action_return_to_validation,
} from 'src/constants';
import { ApiExceptions } from 'src/exceptions';
import type { dynamicObj } from 'src/pages/assets';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  data() {
    return {
      action_assign_to,
      assign_to_option,
      action_restart,
      restart_option,
      action_return_to_validation,
    };
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        if (newVal == true && oldVal == false) {
          return;
        }
        this.initDefault();
      },
    },
  },
  mounted: function () {
    this.initDefault();
  },
  methods: {
   initDefault(){
    if(!this.user_settings[this.action_assign_to]){
      this.user_settings[this.action_assign_to] = 'only_admin'
    }
    if(!this.user_settings[this.action_restart]){
      this.user_settings[this.action_restart] = 'only_admin_assignee'
    }
    if(!this.user_settings[this.action_return_to_validation]) {
      this.user_settings[this.action_return_to_validation] = false
    }
   },
   async updateActionSetting(value: any, key: string) {
    try {
      await this.updateSetting(key, value);
      notify.success(this.$t('save_successfully')); 
    } catch (error: any) {
      const msg = ApiExceptions.getErrorMessage(error as dynamicObj); 
      notify.error(msg);
      logError(error);
    }
   }
  },
  setup() {
    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { updateSetting } = settings_store;

    return {
      updateSetting,
      user_settings,
      loading_settings,
    };
  },
});
</script>

<style lang="scss" scoped></style>
