<template>
  <div class="settings-toggle-item-with-selects">
    <div class="settings-toggle-content">
      <span class="settings-toggle-label">{{ $t('dashboard_status_filter_style') }}</span>
    </div>
    <div class="settings-toggle-selects">
      <q-select
        outlined
        dense
        class="s-field back-white"
        v-model="user_settings[status_filter_style_setting]"
        @update:model-value="
          updateStatusFilterSetting(
            user_settings[status_filter_style_setting],
            status_filter_style_setting,
          )
        "
        :options="status_filter_options"
      />
    </div>
  </div>

  <div
    v-if="user_settings[status_filter_style_setting] == 'Custom'"
    class="settings-toggle-item-with-selects"
  >
    <div class="settings-toggle-content">
      <span class="settings-toggle-label">{{ $t('custom_status_filter') }}</span>
    </div>
    <div class="settings-toggle-selects">
      <q-select
        ref="qselect"
        dense
        multiple
        outlined
        use-input
        v-model="selected_status"
        @filter="filterlistEvent"
        @input="clearFilter"
        class="s-field back-white"
        :options="filtered_status_list"
        :label="$t('status')"
      >
        <template
          v-slot:option="{ itemProps, selected, opt, toggleOption }"
        >
          <q-item v-bind="itemProps">
            <q-item-section side>
              <q-checkbox
                :model-value="selected"
                @update:model-value="toggleOption(opt)"
              ></q-checkbox>
            </q-item-section>
            <q-item-section>
              <div>{{ opt.label }}</div>
            </q-item-section>
          </q-item>
        </template>
      </q-select>
    </div>
    <div class="settings-toggle-actions">
      <f-btn :label="$t('apply')" @click="saveOrgPref()" />
    </div>
  </div>

  <q-inner-loading :showing="loading || loading_settings">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import helperMixin from 'src/mixins/helperMixin.js';
import { useSettingStore, useDocStatusDropdownStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import {
  filters_reset_after_upload_setting,
  filters_reset_after_restart_setting,
  filters_reset_after_export_setting,
  status_filter_style_setting,
  status_filter_list,
  CONSTANTS,
} from 'src/constants';
import documentUtil from 'src/utils/documentUtil';
import { ApiExceptions } from 'src/exceptions';
import type { dynamicObj } from 'src/pages/assets';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  data() {
    return {
      filters_reset_after_upload_setting,
      filters_reset_after_restart_setting,
      filters_reset_after_export_setting,
      status_filter_style_setting,
      status_filter_list,
    };
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        // data loading is done and value never set
        if (newVal == true && oldVal == false) {
          return;
        }
        this.initView();
        this.getStatusesList(CONSTANTS.all);
        this.loadCustomList();
        this.filtered_status_list = this.status_list;
      },
    },
    status_list_loading: {
      handler: function (newVal, oldVal) {
        this.filtered_status_list = this.status_list;
      },
    },
  },
  mounted() {
    this.initView();
    this.getStatusesList(CONSTANTS.all);
    this.loadCustomList();
    this.filtered_status_list = this.status_list;
  },
  methods: {
    initView() {
      if (!this.user_settings[this.filters_reset_after_upload_setting]) {
        this.user_settings[this.filters_reset_after_upload_setting] = false;
      }

      if (!this.user_settings[this.filters_reset_after_restart_setting]) {
        this.user_settings[this.filters_reset_after_restart_setting] = false;
      }

      if (!this.user_settings[this.filters_reset_after_export_setting]) {
        this.user_settings[this.filters_reset_after_export_setting] = false;
      }

      if (!this.user_settings[this.status_filter_style_setting]) {
        this.user_settings[this.status_filter_style_setting] = CONSTANTS.all;
      }
    },

    loadCustomList() {
      if (
        this.user_settings[this.status_filter_style_setting] == CONSTANTS.custom
      ) {
        if (!this.user_settings[this.status_filter_list]) {
          this.selected_status = [];
          return;
        }
        this.user_settings[this.status_filter_list]
          .split(',')
          .forEach((item: any) => {
            let key = item;
            if (documentUtil.methods.getLabelTranslation(item) != '-') {
              this.selected_status.push(
                Object.assign(
                  {},
                  {
                    value: key,
                    label: documentUtil.methods.getLabelTranslation(item),
                  },
                ),
              );
            }
          });
      }
    },
    async updateStatusFilterSetting(value: any, key: string) {
      try {
        await this.updateSetting(key, value);
        notify.success(this.$t('save_successfully'));
      } catch (error: any) {
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
        logError(error);
      }
    },

    saveOrgPref() {
      if (this.selected_status.length == 0) {
        this.user_settings[this.status_filter_style_setting] = CONSTANTS.all;
        this.updateSetting(this.status_filter_style_setting, CONSTANTS.all);
      } else {
        this.updateSetting(this.status_filter_style_setting, CONSTANTS.custom);
        let status_str = '';
        this.selected_status.forEach((status: any) => {
          status_str += status.value + ',';
        });
        this.updateSetting(this.status_filter_list, status_str);
        notify.success(this.$t('operation_sucessfull'));
      }
    },

    filterlistEvent(val: string, update: any, abort: any) {
      if (!val) {
        update(() => {
          this.filtered_status_list = this.status_list;
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.filtered_status_list = this.status_list.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
        );
      });
    },

    clearFilter() {
      if (this.$refs.qselect !== void 0) {
        (this.$refs.qselect as any).updateInputValue('');
      }
    },
  },
  setup() {
    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { updateSetting } = settings_store;

    const status_filter_options = [
      CONSTANTS.all,
      CONSTANTS.static,
      CONSTANTS.custom,
    ];

    const doc_status_dropdown = useDocStatusDropdownStore();
    const { status_list_loading, status_list } =
      storeToRefs(doc_status_dropdown);
    const { getStatusesList } = doc_status_dropdown;

    return {
      updateSetting,
      getStatusesList,
      user_settings,
      loading_settings,
      loading: ref(false),
      status_filter_options: status_filter_options,
      status_list_loading,
      status_list,
      filtered_status_list: ref([] as any),
      selected_status: ref([] as any),
    };
  },
});
</script>

<style lang="scss" scoped></style>
