<template>
  <div class="settings-toggle-item-with-selects">
    <div class="settings-toggle-content">
      <span class="settings-toggle-label">Delivered Orders Visibility</span>
    </div>
    <div class="settings-toggle-selects">
      <q-input
        outlined
        dense
        type="number"
        class="s-field back-white"
        v-model="user_settings[delivered_order_days]"
        @update:model-value="
          updateAdvanceShipmentDays(
            user_settings[delivered_order_days],
            delivered_order_days,
          )
        "
      >
        <template v-slot:append>
          <div class="days-text">Days</div>
        </template>
      </q-input>
    </div>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { useSettingStore } from 'src/store/Settings/setting.store';
import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import { delivered_order_days } from 'src/constants';
import { ApiExceptions } from 'src/exceptions';
import type { dynamicObj } from 'src/pages/assets';
export default defineComponent({
  el: '#app',
    data() {
    return {
      delivered_order_days,
    };
  },
  setup() {
    const settings_store = useSettingStore();
    const { updateSetting } = settings_store;
    const { user_settings } = storeToRefs(settings_store);

    return {
      updateSetting,
      user_settings,
    };
  },
  methods: {
    async updateAdvanceShipmentDays(value: any, key: string) {
      try {
        await this.updateSetting(key, value);
        notify.success(this.$t('save_successfully'));
      } catch (error: any) {
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
        logError(error);
      }
    },
  },
});
</script>

<style scoped>
.days-text {
  font-size: 12px;
  color: #4197b7;
}
</style>
